WITH cleaned AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, DATE_TRUNC('week', order_date) AS order_date_period, CASE WHEN amount >= 1600 THEN 'High' WHEN amount >= 680 THEN 'Medium' ELSE 'Low' END AS amount_band, COALESCE(channel, 'OTHER') AS resolved_channel FROM orders WHERE order_date > DATE '2023-10-03' AND store_id IS NOT NULL) SELECT a.*, b.city FROM cleaned a JOIN stores b ON a.store_id = b.id;
